/* ---------- intake form ---------- */
function intakeSpec(init){return {id:"ppm_intake",title:"New demand request",story:"Anyone can raise a request. Portfolio Agent checks it for duplicates and missing facts as you type, suggests scores, and a sponsor confirms them before the review board sees it.",submit:"Submit request",
 fields:[{section:"What are you asking for"},
  {k:"title",label:"Request title",type:"text",req:true,ph:"For example, Reader feedback widget",wide:true},
  {k:"kind",label:"What kind of work is this?",type:"chips",req:true,opts:WKINDS},
  {k:"why",label:"What problem does it solve, and for whom?",type:"longtext",req:true,wide:true,help:"Two or three sentences. This text is also used to suggest the scores.",ai:{label:"Tighten",fn:v=>(v.why||"").trim().replace(/\s+/g," ").replace(/^./,c=>c.toUpperCase())+((v.why||"").trim().endsWith(".")?"":".")+" Success means a measurable change we can check in 90 days."}},
  {k:"requester",label:"Requested by",type:"people",req:true},{k:"sponsor",label:"Executive sponsor",type:"people",req:true,help:"The person who will answer for the benefit."},
  {section:"How it connects"},
  {k:"svc",label:"Service it changes",type:"select",opts:[["","Not linked"],...SVCREG.map(s=>[s.id,s.n+" ("+s.tier+")"])],help:"Linking a service shows its tier, owner and the projects already touching it."},
  {k:"obj",label:"Strategic objective",type:"select",opts:[["","Choose one"],...OBJS()],help:"Requests with no objective are flagged and cannot reach the review board."},
  {k:"cap",label:"Maturity capability it raises",type:"select",opts:[["","None"],...MATCAP.map(c=>[c,c])]},
  {section:"How it scores"},
  {k:"strat",label:"Strategic fit (0 to 5)",type:"range",min:0,max:5,step:1,ai:{label:"Suggest",fn:v=>suggest(v).s}},
  {k:"risk",label:"Risk reduction (0 to 5)",type:"range",min:0,max:5,step:1,ai:{label:"Suggest",fn:v=>suggest(v).r}},
  {k:"urg",label:"Urgency (0 to 5)",type:"range",min:0,max:5,step:1,ai:{label:"Suggest",fn:v=>suggest(v).u}},
  {k:"hard",label:"Hard date, if one exists",type:"date",show:v=>v.kind==="Compliance mandate"||+v.urg>=4,help:"A regulator, contract or event that fixes the timing."},
  {section:"What it costs and returns"},
  {k:"cost",label:"Estimated cost",type:"number",unit:" K",min:1,req:true,ph:"420"},{k:"ben",label:"3-year benefit",type:"number",unit:" K",min:0,req:true,ph:"1100"},
  {k:"pm",label:"Effort in person-months",type:"number",min:1,req:true,ph:"14"},
  {k:"teams",label:"Teams needed",type:"multi",opts:Object.keys(CAP)},
  {k:"fte",label:"People per team (FTE)",type:"number",min:1,ph:"2"},
  {k:"file",label:"Attach a brief",type:"file",help:"For a contract, use the SOW and contract analyzer, which reads milestones, service levels and invoice dates."}],
 live:v=>{if(!v.title&&!v.why)return "Start with a title and the reason. Portfolio Agent checks for duplicates and shows the score before you submit.";const dp=dupOf(v);const tmp={id:"NEW",n:v.title||"New request",cost:+v.cost||0,ben:+v.ben||0,strat:+v.strat||0,risk:+v.risk||0,urg:+v.urg||0,pm:+v.pm||0,res:[],st:0,who:"",sp:"",why:""};
  DEMAND.push(tmp);const L=rank(S.w,S.env,S.cap),r=L.find(x=>x.id==="NEW");DEMAND.pop();const sc=r?r.score:dscore(tmp,S.w),pos=L.findIndex(x=>x.id==="NEW")+1;const miss=[!v.obj&&"an objective",!+v.cost&&"a cost",!+v.ben&&"a benefit"].filter(Boolean);const sv=v.svc?svcOf(v.svc):null;
  return `<b>Score preview: ${sc}</b> of 100, would rank <b>#${pos}</b> of ${L.length} and sit ${r&&r.fund?"<b>inside</b>":"<b>below</b>"} the funding line at the ${K$(S.env)} envelope.<br><span class="muted">Formula: (${W4().s.toFixed(2)} × fit + ${W4().f.toFixed(2)} × return + ${W4().r.toFixed(2)} × risk + ${W4().u.toFixed(2)} × urgency) ÷ 5 × 100</span>${sv?`<br><span class="muted">It changes <b>${esc3(sv.n)}</b> (${esc3(sv.tier)}, owner ${esc3(sv.owner)}), which ${sv.proj&&sv.proj.length?"already has "+sv.proj.length+" project"+(sv.proj.length>1?"s":"")+" touching it":"has no project today"}.</span>`:""}${dp?`<br><span style="color:var(--warn)"><b>Possible duplicate of ${esc3(dp.d.n)}</b> (${dp.pct}% of the wording overlaps). Consider adding to that request instead.</span>`:""}${miss.length?`<br><span class="muted">Still missing: ${miss.join(", ")}. The request can be saved, but it cannot reach the review board without them.</span>`:""}`},
 onSubmit:v=>{const id="D"+(Math.max(...DEMAND.map(d=>+String(d.id).slice(1)||0))+1),teams=(v.teams&&v.teams.length?v.teams:["Platform team"]).map(t=>[t,+v.fte||1]);
  DEMAND.push({id,n:v.title,who:v.requester,sp:v.sponsor,cost:+v.cost,ben:+v.ben,strat:+v.strat||0,risk:+v.risk||0,urg:+v.urg||0,pm:+v.pm,st:0,res:teams,m0:6,mo:Math.max(2,Math.round(v.pm/(teams.length*(+v.fte||1)))),why:v.why,obj:v.obj||"",hard:v.hard||"",svc:v.svc||"",wk:v.kind,cap:v.cap||""});
  S.v.port=0;const dp=dupOf(v);return {toast:`${id} submitted. Portfolio Agent is screening it now.`,audit:id+" "+v.title+(dp?" (possible duplicate of "+dp.d.id+")":"")}},defaults:Object.assign({strat:3,risk:2,urg:2,kind:"New capability"},init||{})}}
