DND.on("ppmst",(id,from,to)=>{const f=+from.split(":")[1],t=+to.split(":")[1],d=DEMAND.find(x=>x.id===id);if(!d||f===t)return;
 if(S.conv[id]){toast("This request is already a project","info");return render()}
 if(t>=3&&!d.obj){toast("Link a strategic objective before it can go to the review board.","bad");return render()}
 if(t>=2&&(!d.cost||!d.ben)){toast("Add cost and benefit before scoring.","bad");return render()}
 d.st=t;delete S.dst[id];audit("moved demand",d.id+" to "+DSTAGES[t]);toast(`${d.n} moved to ${DSTAGES[t]}`,"good");render()});

const tok=s=>new Set((s||"").toLowerCase().replace(/[^a-z0-9 ]/g," ").split(/\s+/).filter(w=>w.length>3&&!/^(that|this|with|from|have|will|their|them|than|more|into|your|they|when)$/.test(w)));
