 return DIR.map(r=>{let lv=skillLvl(r.name,rq.skill);if(!lv){const sub=(r.skills||[]).find(x=>x.toLowerCase().includes(sk.slice(0,5)));if(sub)lv=2}return {r,lv,h:headroom(r)}}).filter(x=>x.lv>=2&&x.h>=Math.min(8,rq.hrs/2)&&!taken.has(x.r.name)&&!(x.r.kind==="contractor"&&x.r.end&&wdOf(x.r.end)<to)&&(rq.pref==="any"||x.r.kind===rq.pref||(rq.pref==="human"&&x.r.kind==="human")))
