const SKILLS=[];window.SKILLS=SKILLS;
function syncSkills(){const have=new Set(SKILLS.map(s=>s.id));DIR.forEach(r=>{(r.skills||[]).forEach(sk=>{const k=r.name+"|"+sk;if(have.has(k))return;have.add(k);const g=RNG(k)();SKILLS.push({id:k,person:r.name,skill:sk,level:2+Math.floor(g*4),verified:g>.55})})});for(let i=SKILLS.length-1;i>=0;i--)if(!who(SKILLS[i].person))SKILLS.splice(i,1)}
