  live:v=>{if(!v.who)return "";const r=who(v.who),Pl=curPlan(),ef=Pl.R[tk.id].ef,out=[];if(r.kind==="contractor"&&r.end&&wdOf(r.end)<ef)out.push({sev:"bad",txt:`${r.name}'s contract ends ${fmtISO(r.end)}, before this task ends (${fmtD(ef-1,1)}).`});if(r.kind==="ai"&&!P.acc[r.name])out.push({sev:"bad",txt:`${r.name} has no human accountable owner yet.`});if(r.kind==="msp"&&wlOf(r.name).pct>85)out.push({sev:"warn",txt:`${r.name} is near contracted capacity.`});if((r.kind==="human"||r.kind==="contractor")&&wlOf(r.name).pct>100)out.push({sev:"warn",txt:`${r.name} is over capacity.`});return `${kindPill(r.kind)} <span class="muted">${esc3(capLine(r.name))}</span>${chkHtml(out)}`},
