function raidBoard(L){const cap=12;return `<div class="kan">${["open","active","done"].map((s,i)=>{const it=L.filter(r=>r.s===s).sort((a,b)=>expo(b)-expo(a)),sh=it.slice(0,cap);return `<div class="kcol glass"><div class="khead"><b>${["Not started","In progress","Done"][i]}</b><span class="pill mute" data-role="metric">${it.length}</span></div><div class="kl" data-dnd="rd:${s}" data-dnd-scope="ppmraid">${sh.map(r=>`<div class="kcard" data-dnd-id="${r.id}" data-ppm-ritem="${r.id}" tabindex="0" role="button"><span class="row" style="gap:6px;align-self:flex-start">${tpill(r)}<span class="muted small">${lab(r)}</span></span><b data-role="story">${esc3(r.n)}</b><span class="muted small row" style="gap:6px">${avatar(r.own,{size:20})}${esc3(r.own)} · ${esc3(pshort(r.p))}${r.t==="R"?" · "+K$(expo(r)):""}</span></div>`).join("")||'<span class="muted small" style="padding:8px">Drop here.</span>'}${it.length>cap?`<span class="muted small" style="padding:6px">${it.length-cap} more, highest exposure first. See the register.</span>`:""}</div></div>`}).join("")}</div>`}
function raidHeat(L){const rs=L.filter(r=>(r.t==="R"||r.t==="A")&&r.s!=="done");let g='<div class="ppm-heat"><span class="hy">Probability, rows 5 (top) to 1</span>';for(let pr=5;pr>=1;pr--){g+=`<span class="ppm-hl"><b>${pr}</b><small>${Math.round(PRB[pr]*100)}%</small></span>`;for(let im=1;im<=5;im++){const sc=pr*im,c=sc>=15?"bad":sc>=8?"warn":"good",cell=rs.filter(r=>r.pr===pr&&r.im===im);g+=`<div class="hc ${c}" data-dnd="h:${pr}:${im}" data-dnd-scope="ppmheat" title="${cell.length} item${cell.length===1?"":"s"}: probability ${pr} × impact ${im} = ${sc}">${cell.length<=6?cell.map(r=>`<span class="hd ${r.t==="A"?"asm":""}" data-dnd-id="${r.id}" data-ppm-ritem="${r.id}" tabindex="0" title="${esc3(r.id+" "+r.n)}">${r.id.replace(/^[A-Z]-X?0*/,"")}</span>`).join(""):`<button class="hcount" data-ppm-cell="${pr}:${im}" title="Open the ${cell.length} items in this cell"><b class="num">${cell.length}</b><small>items</small></button>`}</div>`}}g+='<span></span>'+[1,2,3,4,5].map(i=>`<span class="ppm-hl ppm-hx"><b>${i}</b><small>${["Minor","Moderate","Serious","Major","Severe"][i-1]}</small></span>`).join("")+'<span class="hy" style="text-align:center">Impact, columns 1 to 5</span></div>';
 const top=rs.filter(r=>r.t==="R").sort((a,b)=>expo(b)-expo(a)).slice(0,6);
 return `<div class="grid g2" style="align-items:start"><section class="card glass"><div class="cardhead"><div><h3>Risk heat map</h3><span class="muted small">Drag a dot to change its probability and impact. Cells with more than six items show a count.</span></div></div>${g}${legend([["Low: rating under 8","--good-f"],["Medium: 8 to 14","--warn-f"],["High: 15 or more","--bad-f"]])}<div class="legend-row" style="margin-top:8px"><span>Rating is probability (1 to 5) × impact (1 to 5). Dot labels are the item number, for example 101 is R-101. A dark dot is a risk, an outlined dot an assumption.</span></div></section><section class="card glass"><div class="cardhead"><div><h3>Largest exposures</h3><span class="muted small">Probability × cost impact</span></div>${fchip("m_raid")}</div><div class="needs">${top.map(r=>`<button class="need" data-ppm-ritem="${r.id}" style="grid-template-columns:minmax(0,1fr) auto"><div><b>${esc3(r.n)}</b><span class="muted">${Math.round(prob(r)*100)}% × ${K$(r.cost)} · ${esc3(pshort(r.p))} · ${esc3(r.own)}</span></div><b class="num" data-role="metric">${K$(expo(r))}</b></button>`).join("")||empty("No open risks","Nothing matches the filters.")}</div></section></div>`}
function raidLinked(L){const gk=KORD.map(k=>({key:k,label:KS[k],rows:L.filter(r=>kindOf(r.own)===k&&r.s!=="done").map(r=>({id:r.id,t:r.n,sub:r.own+" · "+pshort(r.p),tag:RT[r.t][0],st:r.t==="R"?"bad":r.t==="I"?"warn":"mute",go:()=>itemDrawer(r.id)}))})).filter(g=>g.rows.length),pj=[...new Set(L.map(r=>r.p))].map(pid=>({key:pid,label:pid+" "+((prjOf(pid)||{}).full||(prjOf(pid)||{}).n||""),rows:L.filter(r=>r.p===pid&&r.s!=="done").map(r=>({id:r.id,t:r.n,sub:r.own,tag:RT[r.t][0],st:r.t==="R"?"bad":r.t==="I"?"warn":"mute",go:()=>itemDrawer(r.id)}))})).filter(g=>g.rows.length);
 return `<div class="grid g2" style="align-items:start"><section class="card glass"><div class="cardhead"><div><h3>By kind of owner</h3><span class="muted small" data-role="story">Items can be owned by an employee, an AI agent, a contractor or a managed service provider. AI-owned items name a human who is accountable.</span></div></div>${lrHTML({id:"ppm-rl-kind",groups:gk,limit:6,search:true})}</section><section class="card glass"><div class="cardhead"><div><h3>By project</h3><span class="muted small">Open items grouped under each project</span></div></div>${lrHTML({id:"ppm-rl-proj",groups:pj,limit:6,search:true})}</section></div>`}
